#[test]
fn include_inactive_emits_inactive_concepts() {
    // Regression test for `--include-inactive`. The inactive concept 9468002 was
    // dropped at RF2 load time regardless of the flag; it must now appear, with
    // `active = false` and its term fully populated from its (still-active) FSN.
    let dir = tempfile::tempdir().unwrap();
    let ndjson = dir.path().join("syn.ndjson");
    ndjson::run(ndjson::Args {
        rf2_dirs: vec![fixture_dir()],
        locale: "en-GB".to_string(),
        output: Some(ndjson.clone()),
        include_inactive: true,
        refsets: RefsetMode::Simple,
    })
    .unwrap();

    let records = read_records(&ndjson);
    // All 23 fixture concepts now, exactly one of them inactive.
    assert_eq!(records.len(), 23);
    assert_eq!(records.iter().filter(|r| !r.active).count(), 1);

    let inactive = record(&records, "9468002");
    assert!(!inactive.active);
    assert_eq!(inactive.fsn, "Inactive example disorder (disorder)");
    assert_eq!(inactive.preferred_term, "Inactive example disorder");

    // Active concepts are unaffected: every other record is still active.
    assert!(records
        .iter()
        .filter(|r| r.id != "9468002")
        .all(|r| r.active));
}

#[test]
fn sqlite_rebuild_replaces_all_ndjson_derived_data() {
    let dir = tempfile::tempdir().unwrap();
    let inactive_ndjson = dir.path().join("inactive.ndjson");
    let active_ndjson = dir.path().join("active.ndjson");
    let db = dir.path().join("syn.db");

    for (output, include_inactive) in [(&inactive_ndjson, true), (&active_ndjson, false)] {
        ndjson::run(ndjson::Args {
            rf2_dirs: vec![fixture_dir()],
            locale: "en-GB".to_string(),
            output: Some(output.clone()),
            include_inactive,
            refsets: RefsetMode::Simple,
        })
        .unwrap();
    }

    sqlite::run(sqlite::Args {
        input: inactive_ndjson,
        output: Some(db.clone()),
        transitive_closure: true,
        include_self: false,
    })
    .unwrap();

    let active_records = read_records(&active_ndjson);
    let expected_isa: i64 = active_records
        .iter()
        .map(|record| record.parents.len() as i64)
        .sum();
    let expected_relationships: i64 = active_records
        .iter()
        .map(|record| record.relationships.len() as i64)
        .sum();

    for _ in 0..2 {
        sqlite::run(sqlite::Args {
            input: active_ndjson.clone(),
            output: Some(db.clone()),
            transitive_closure: false,
            include_self: false,
        })
        .unwrap();

        let conn = Connection::open(&db).unwrap();
        let count = |query: &str| -> i64 { conn.query_row(query, [], |row| row.get(0)).unwrap() };
        assert_eq!(
            count("SELECT COUNT(*) FROM concepts"),
            active_records.len() as i64
        );
        assert_eq!(count("SELECT COUNT(*) FROM concept_isa"), expected_isa);
        assert_eq!(
            count("SELECT COUNT(*) FROM concept_relationships"),
            expected_relationships
        );
        assert_eq!(
            conn.query_row(
                "SELECT COUNT(*) FROM concepts WHERE active = 0",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap(),
            0
        );
        assert_eq!(
            conn.query_row(
                "SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = 'concept_ancestors'",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap(),
            0
        );

        let header = std::fs::read_to_string(&active_ndjson).unwrap();
        let expected_fingerprint = sct_rs::provenance::try_parse_ndjson_line(
            header.lines().next().expect("provenance header"),
        )
        .unwrap()
        .content_fingerprint;
        let actual_fingerprint = sct_rs::provenance::read_sqlite(&conn)
            .unwrap()
            .unwrap()
            .content_fingerprint;
        assert_eq!(actual_fingerprint, expected_fingerprint);
    }
}

