/// Regression test: without a transitive-closure table, the subtree count
/// must fall back to a recursive CTE rather than erroring out. It previously
/// propagated SQLite's "query returned no rows" through `?` instead of
/// treating a missing `concept_ancestors` table as `has_tct = false`.
#[test]
fn size_estimate_without_transitive_closure_table() {
    let (_d, _ndjson, db) = build_all("en-GB");
    let conn = Connection::open(&db).unwrap();

    let has_tct: bool = conn
        .query_row(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='concept_ancestors'",
            [],
            |_| Ok(true),
        )
        .unwrap_or(false);
    assert!(
        !has_tct,
        "fixture db unexpectedly has a transitive-closure table"
    );

    // Diabetes mellitus (73211009) plus its two children = 3 concepts,
    // matching the `<<73211009` ECL result asserted elsewhere in this suite.
    let est = size::estimate_sizes(&conn, "73211009", 50).unwrap();
    assert_eq!(est.subtree_count, 3);
}

#[test]
fn size_builds_tct_when_missing() {
    use sct_rs::commands::size::{self, Args};
    use sct_rs::output::OutputFormat;

    let (_d, _ndjson, db) = build("en-GB");

    // Drop the TCT to simulate a database without one.
    {
        let conn = Connection::open(&db).unwrap();
        conn.execute("DROP TABLE concept_ancestors", []).unwrap();
    }

    // Run `sct size --build-tct`, which should rebuild the TCT and proceed.
    let args = Args {
        concept: None, // defaults to root (138875005)
        sample: 50,
        tree: false,
        depth: 2,
        format: OutputFormat::Text,
        build_tct: true, // the flag under test
        db: Some(db.clone()),
    };
    size::run(args).unwrap();

    // Verify the TCT was rebuilt.
    {
        let conn = Connection::open(&db).unwrap();
        let has_tct: bool = conn
            .query_row(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='concept_ancestors'",
                [],
                |_| Ok(true),
            )
            .unwrap_or(false);
        assert!(has_tct, "concept_ancestors table should have been rebuilt");

        let row_count: i64 = conn
            .query_row("SELECT COUNT(*) FROM concept_ancestors", [], |r| r.get(0))
            .unwrap();
        assert!(row_count > 0, "concept_ancestors should contain rows");
    }
}

// ---------------------------------------------------------------------------
// R16: `sct mcp` tool handlers, driven through the JSON-RPC dispatcher over the
// committed synthetic fixture (the same RF2 -> NDJSON -> SQLite DB the rest of
// this file builds). Exercises the tool layer end-to-end, not just the SQL.
// ---------------------------------------------------------------------------
mod mcp_tools {
    use super::{build, EXAMPLE_REFSET};
    use rusqlite::Connection;
    use sct_rs::commands::mcp;
    use serde_json::json;

    /// Call one tool through the domain-level MCP adapter and return its JSON.
    /// Separate process tests cover the protocol lifecycle and wire format.
    fn tool_text(conn: &Connection, name: &str, arguments: serde_json::Value) -> String {
        let result = mcp::call_tool_for_test(conn, name, arguments)
            .unwrap_or_else(|error| panic!("{name} failed: {error:#}"));
        serde_json::to_string_pretty(&result).unwrap()
    }

    #[test]
    fn search_matches_preferred_terms_and_synonyms() {
        let (_d, _n, db) = build("en-GB");
        let conn = Connection::open(&db).unwrap();

        // Preferred-term / FSN match: "diabetes" -> the two diabetes children.
        let out = tool_text(&conn, "snomed_search", json!({ "query": "diabetes" }));
        assert!(
            out.contains("46635009"),
            "diabetes search missing type 1: {out}"
        );
        assert!(
            out.contains("44054006"),
            "diabetes search missing type 2: {out}"
        );

        // Synonym match: "heart" is only in MI's synonym "Heart attack".
        let out = tool_text(&conn, "snomed_search", json!({ "query": "heart" }));
        assert!(out.contains("22298006"), "synonym search missing MI: {out}");

        let out = tool_text(
            &conn,
            "snomed_search",
            json!({ "query": "unmatched \" quote" }),
        );
        assert!(out.contains("No results found"), "unmatched quote: {out}");
    }

    #[test]
    fn concept_returns_detail() {
        let (_d, _n, db) = build("en-GB");
        let conn = Connection::open(&db).unwrap();
        let out = tool_text(&conn, "snomed_concept", json!({ "id": "22298006" }));
        assert!(out.contains("Myocardial infarction"), "{out}");
        assert!(out.contains("Clinical finding"), "{out}");
    }

    #[test]
    fn children_and_ancestors_walk_the_isa_graph() {
        let (_d, _n, db) = build("en-GB");
        let conn = Connection::open(&db).unwrap();

        // Diabetes mellitus (73211009) -> type 1 (46635009) + type 2 (44054006).
        let kids = tool_text(&conn, "snomed_children", json!({ "id": "73211009" }));
        assert!(
            kids.contains("46635009") && kids.contains("44054006"),
            "children: {kids}"
        );

        // Type 1 DM (46635009) -> ancestors include Diabetes mellitus (73211009).
        let anc = tool_text(&conn, "snomed_ancestors", json!({ "id": "46635009" }));
        assert!(anc.contains("73211009"), "ancestors: {anc}");
    }

    #[test]
    fn hierarchy_lists_members() {
        let (_d, _n, db) = build("en-GB");
        let conn = Connection::open(&db).unwrap();
        let out = tool_text(
            &conn,
            "snomed_hierarchy",
            json!({ "hierarchy": "Clinical finding" }),
        );
        assert!(out.contains("22298006"), "hierarchy members: {out}");
    }

    #[test]
    fn map_ctv3_code_to_snomed() {
        let (_d, _n, db) = build("en-GB");
        let conn = Connection::open(&db).unwrap();
        let out = tool_text(
            &conn,
            "snomed_map",
            json!({ "code": "X200", "terminology": "ctv3" }),
        );
        assert!(out.contains("22298006"), "ctv3 X200 -> MI: {out}");
    }

    #[test]
    fn refsets_and_members() {
        let (_d, _n, db) = build("en-GB");
        let conn = Connection::open(&db).unwrap();

        let refsets = tool_text(&conn, "snomed_refsets", json!({}));
        assert!(refsets.contains(EXAMPLE_REFSET), "refsets list: {refsets}");

        let members = tool_text(
            &conn,
            "snomed_refset_members",
            json!({ "refset_id": EXAMPLE_REFSET }),
        );
        assert!(
            members.contains("46635009") && members.contains("44054006"),
            "refset members: {members}"
        );
    }

    #[test]
    fn refset_compare_and_profile() {
        let (_d, _n, db) = build("en-GB");
        let conn = Connection::open(&db).unwrap();

        // Comparing the refset against itself: everything is in-both, nothing
        // is only-in-a/only-in-b - still exercises the full tool round trip
        // (the fixture only carries one loaded Simple refset).
        let cmp = tool_text(
            &conn,
            "snomed_refset_compare",
            json!({ "refset_id_a": EXAMPLE_REFSET, "refset_id_b": EXAMPLE_REFSET }),
        );
        assert!(
            cmp.contains("46635009") && cmp.contains("44054006"),
            "refset compare: {cmp}"
        );
        let parsed: serde_json::Value = serde_json::from_str(&cmp).unwrap();
        assert_eq!(parsed["only_in_a"]["count"], 0, "compare: {cmp}");
        assert_eq!(parsed["only_in_b"]["count"], 0, "compare: {cmp}");
        assert_eq!(parsed["in_both"]["count"], 2, "compare: {cmp}");

        // Type 1 + type 2 diabetes are both "Clinical finding".
        let profile = tool_text(
            &conn,
            "snomed_refset_profile",
            json!({ "refset_id": EXAMPLE_REFSET }),
        );
        assert!(
            profile.contains("Clinical finding") && profile.contains('2'),
            "refset profile: {profile}"
        );
    }
}
